import type { Meta, StoryObj } from '@storybook/react'
import { expect, fn, userEvent, within } from '@storybook/test'

import { Button } from './button'

const meta = {
  title: 'Primitives/Button',
  component: Button,
  tags: ['autodocs'],
  args: { children: 'Save changes', onClick: fn() },
  argTypes: {
    variant: { control: 'select', options: ['default', 'secondary', 'outline', 'ghost', 'success', 'destructive'] },
    size: { control: 'select', options: ['default', 'sm', 'compact', 'icon'] }
  }
} satisfies Meta<typeof Button>

export default meta
type Story = StoryObj<typeof meta>

export const Primary: Story = {}

export const FinancialActions: Story = {
  render: () => (
    <div className="flex flex-wrap items-center gap-3">
      <Button>Save draft</Button>
      <Button variant="secondary">Export CSV</Button>
      <Button variant="outline">Discuss</Button>
      <Button variant="success">Reconcile</Button>
      <Button variant="destructive">Void transaction</Button>
    </div>
  )
}

export const DenseTableActions: Story = {
  render: () => (
    <div className="flex items-center gap-2 rounded-md border bg-card p-3 shadow-card">
      <span className="mr-4 text-sm text-muted-foreground">Imported bank transaction</span>
      <Button size="compact" variant="outline">Match</Button>
      <Button size="compact" variant="ghost">Transfer</Button>
      <Button size="compact" variant="success">OK</Button>
    </div>
  )
}

export const Disabled: Story = { args: { disabled: true, children: 'Processing' } }

export const ClickInteraction: Story = {
  play: async ({ canvasElement, args }) => {
    const canvas = within(canvasElement)
    await userEvent.click(canvas.getByRole('button', { name: 'Save changes' }))
    await expect(args.onClick).toHaveBeenCalledTimes(1)
  }
}
